CREATE TABLE IF NOT EXISTS legal_documents (
  id TEXT PRIMARY KEY,
  title TEXT NOT NULL,
  "originalTitle" TEXT,
  "documentType" TEXT NOT NULL CHECK ("documentType" IN ('constitution','act','regulation','schedule_only')),
  "yearBs" NUMERIC NOT NULL,
  "yearAd" NUMERIC NOT NULL,
  "totalPages" INTEGER NOT NULL CHECK ("totalPages" >= 0),
  nodes JSONB NOT NULL
);

INSERT INTO legal_documents (id,title,"originalTitle","documentType","yearBs","yearAd","totalPages",nodes) VALUES (
  $LEGAL_9d26a67011a98f$doc_passport_act_2076$LEGAL_9d26a67011a98f$,
  $LEGAL_9d26a67011a98f$Passport Act, 2076 (2019)$LEGAL_9d26a67011a98f$,
  NULL,
  $LEGAL_9d26a67011a98f$act$LEGAL_9d26a67011a98f$,
  2076,
  2019,
  12,
  $LEGAL_9d26a67011a98f${"id":"doc_passport_act_2076","title":"Passport Act, 2076 (2019)","originalTitle":null,"documentType":"act","yearBs":2076,"yearAd":2019,"totalPages":12,"nodes":[{"tier":1,"nodeType":"preamble","identifier":"Preamble","title":"Introductory matter","content":"Passport Act, 2019 (2076)\nDate of Authentication\n14 October, 2019 (2076.6.27)\nAct Number 11 of the Year 2019 (2077)\nAn Act made to amend and consolidate laws regarding passports\nPreamble: Whereas, it is expedient to amend and consolidate prevailing laws in order to regulate\nand manage the matters regarding passports including issuance of passport, travel document to\nthe Nepali Citizens who intend to visit foreign countries;\nNow, therefore, the Federal Parliament enacts this Act.","children":[]},{"tier":1,"nodeType":"chapter","identifier":"Chapter -1","title":null,"content":"Preliminary","children":[{"tier":2,"nodeType":"rule","identifier":"1","title":"Short Title and Commencement","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"This Act may be called \"Passport Act, 2019 (2077)\".","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"This Act shall come into force immediately.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"2","title":"Definition","content":"Unless the subject or the context otherwise requires, in this Act:-","children":[{"tier":3,"nodeType":"clause","identifier":"(a)","title":null,"content":"\"Prescribed\" or \"A s prescribed\" means the prescribed or as\nprescribed pursuant to the Rules framed under this Act or in an order\nissued by the Government of Nepal by a notification published in\nthe Nepal Gazette.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(b)","title":null,"content":"\"Mission\" means Nepal embassy, permanent mission, Nepali\nconsulate general, consulate, special mission located in any foreign\ncountry and also includes any office established in foreign country\nby the Government of Nepal to operate diplomatic business.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(c)","title":null,"content":"\"Ministry\" means the Ministry of Foreign Affairs , Government of\nNepal.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(d)","title":null,"content":"\" Travel Document\" means a travel document to be issued pursuant\nto Section 17.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(e)","title":null,"content":"\"Passport\" means a machine readable, electronic or biometric\npassport to be provided by the Government of Nepal to the Nepali\ncitizen intending to visit abroad.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(f)","title":null,"content":"\"Department\" means Department of Passports.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(g)","title":null,"content":"\"Travel in course of government business \" means travel for\nprescribed business pursuant to a decision of the Federal and\nProvincial Government and subordinated bodies, local level,\nFederal Parliament, Provincial Assembly and Constitutional Bodies\nand also the travel on formal invitation of the foreign government,\nsemi- governmental and internationally accredited organizations.","children":[]}]}]},{"tier":1,"nodeType":"chapter","identifier":"Chapter-2","title":null,"content":"Regarding Passport","children":[{"tier":2,"nodeType":"rule","identifier":"3","title":"Passport to be received","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"A Nepali citizen shall have to travel abroad along with the\nvalid term passport.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"Notwithstanding anything contained in sub -section (1) if there is no need of\npassport to a Nepali citizen to travel to any country pursuant to the treaty, agreement\nconcluded between the Government of Nepal and any foreign State or Government, the\nNepali citizen may travel to such country without the passport.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"4","title":"Issuance of passport","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"It shall be the power of the Government of Nepal to issue a\npassport.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"The Department shall on behalf of the Government of Nepal, perform the act of\nissuing a passport pursuant to sub-section (1).","children":[]},{"tier":3,"nodeType":"clause","identifier":"(3)","title":null,"content":"The Department shall while issuing a passport issue in accordance with the\nprevailing standards of the International Civil Aviation Organization (ICAO).","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"5","title":"Types of passport","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"The types of passports to be issued pursuant to Section 4 shall be\nas follows:-\n(a) Diplomatic Passport,\n(b) Official Passport,\n(c) Service Passport,\n(d) Ordinary Passport","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"The term of period of the passport to be issued pursuant to sub-section (1) shall\nbe as prescribed.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"6","title":"Diplomatic passport","content":"The Department shall issue a diplomatic passport to the officials\ntravelling abroad in course of government business or special work, as prescribed, upon a\ndecision of or recommendation by the concerned Ministry, Constitutional body or\nSecretariat.","children":[]},{"tier":2,"nodeType":"rule","identifier":"7","title":"Official passport","content":"The Department shall issue an official passport to the officials and\nemployees travelling abroad in course of government business, study, study visit or\ntraining on nomination from the Government of Nepal, Provincial Government or any\ngovernment body, as prescribed, upon request from the concerned body along with the\ndecision thereof.","children":[]},{"tier":2,"nodeType":"rule","identifier":"8","title":"Service passport","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"The Department shall issue a service passport to the private assistant\nto the ambassador, permanent representative, special representative, consular general and\nemployees of gazetted level and classless employee upon written request from the Ministry.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"The Department may issue a service passport to a Nepali citizen working as\nlocal employee in the mission upon written request from the Ministry or the mission.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"9","title":"Ordinary p assport","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"The D epartment may issue an o rdinary passport to the Nepali\ncitizen.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"Other provisions related to ordinary passport shall be as prescribed.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"10","title":"To submit application for passport","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"The Nepali citizen desiring to have a passport\nshall submit an application to the Department, mission or the prescribed body in a\nprescribed format enclosing the original or copy of the Nepali citizenship certificate or the\noriginal or copy of the national identity card issued by the Government of Nepal and\ndocuments as prescribed.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"Notwithstanding anything contained in sub -section (1), in case of a minor\nNepali citizen who is below than sixteen years of age, any one from among his or her father,\nmother, guardian or curator shall submit an application along with him or her and also\nenclosing the documents as prescribed.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(3)","title":null,"content":"The department may issue a passport in the name of a minor in the following\nconditions even though the application is not submitted by any one from among his or her\nfather, mother, guardian or curator:-\n(a) in case the court issued an order to issue a passport in the name of\nsuch minor, or\n(b) in other conditions as prescribed.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(4)","title":null,"content":"If the Department considers fit to issue a passport upon inquiry made to the\napplications submitted for the passports pursuant to sub -section (1) or (2), shall issue\npassports by maintaining a record thereto.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"11","title":"Issuance of a passport","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"The body to which the application is submitted for passport\nshall issue the passport maintaining the record thereof.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"The other provisions related to distribution of passport shall be as prescribed.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"12","title":"Not to issue a passport or to withhold passport","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"Notwithstanding anything contained\nelsewhere in this Act, a passport may not be issued or may be withheld in the name of the\nfollowing persons:-\n(a) upon receipt of the writ ten request from the investigating authority not to\nissue a passport or to withhold a passport in course of the investigation of\nthe charge of the offence related to passport, immigration, corruption,\nmoney laundering, human trafficking, abduction, narcotic drugs, illegal\ntransaction of arms and ammunition, organized crime or terrorism,\n(b) upon receipt of an order of the Court not to issue a passport or to withhold\na passport in the case subjudice in the court in charge of the offence related\nto passport, immigration, corruption, money laundering, human trafficking,\nabduction, narcotic drugs, illegal transaction of arms and ammunition,\norganized crime or terrorism,\n(c) upon serving a sentence upon conviction from the Court in charge of the\noffence related to passport, immigration, corruption, money launderi ng,\nhuman trafficking, abduction, narcotic drugs, illegal transaction of arms and\nammunition, organized crime or terrorism,\n(d) upon enlisted in black list upon default of payment of the loan of the bank\nand financial institution,\n(e) upon restriction on travelling abroad or not to issue a passport or to withhold\na passport issued by an order of the Government of Nepal or of the Court\nwith reasonable grounds,\n(f) when a decision has been made as not to issue a passport or withhold\npassport specifying the reasons thereof by the body issuing passport,\n(g) when valid period of more than one year remains in the passport issued in\nthe name of the passport holder.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"If the Department does not issue an ordinary passport by the reason as specified\nin sub-section (1), it shall provide information thereof to the concerned applicant.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(3)","title":null,"content":"In case the court orders to issue a passport or not to withhold it under the\ncondition of clause (a) of sub-section (1), a passport shall be issued in the name of such a\nperson.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(4)","title":null,"content":"The passport shall be issued in the name of the person if he or she is acquitted\nfrom the Court for the offence pursuant to clause (b) of sub -section (1) or if he or she has\nserved the sentence in accordance with the law for the offence pursuant to clause (d).","children":[]},{"tier":3,"nodeType":"clause","identifier":"(5)","title":null,"content":"A passport may be issued in the name of the person upon receipt of non-\nexistence of the conditions pursuant to clauses (d), (e) or (f) of sub-section (1) in his or her\nregard.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"13","title":"More than one passport may be issued","content":"Notwithstanding anything contained elsewhere\nin this Act, a new passport may, even though the term of the earlier passport remains valid,\nbe issued in the following conditions:-","children":[{"tier":3,"nodeType":"clause","identifier":"(a)","title":null,"content":"in case a diplomatic or official passport holder submits an\napplication for the ordinary passport,","children":[]},{"tier":3,"nodeType":"clause","identifier":"(b)","title":null,"content":"in case an ordinary passport holder submits an application for the\ndiplomatic or official passport in accordance with the prevailing\nlaws.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"14","title":"Passport may be issued even though its valid period remains","content":"Notwithstanding\nanything contained in clause (g) of s ub-section (1) of Section 12, a new passport may be\nissued, even though the term of the passport issued in the name of the passport holder\nremains valid for more than one year in the following conditions:-","children":[{"tier":3,"nodeType":"clause","identifier":"(a)","title":null,"content":"in case the passport is not readable being old, tampered, withered or\nnot being able to use due to error in details thereof,","children":[]},{"tier":3,"nodeType":"clause","identifier":"(b)","title":null,"content":"in case no adequate pages left in the passport,","children":[]},{"tier":3,"nodeType":"clause","identifier":"(c)","title":null,"content":"in case of change of surname,","children":[]},{"tier":3,"nodeType":"clause","identifier":"(d)","title":null,"content":"in case the passport prepared by the Department gets lost or\ndestroyed prior to its distribution to the concerned person,","children":[]},{"tier":3,"nodeType":"clause","identifier":"(e)","title":null,"content":"in case the minor intends to have a passport before attaining sixteen\nyears of age,","children":[]},{"tier":3,"nodeType":"clause","identifier":"(f)","title":null,"content":"in case the passport has been issued in special circumstance,","children":[]},{"tier":3,"nodeType":"clause","identifier":"(g)","title":null,"content":"in other conditions as prescribed.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"15","title":"Passport may be cancelled","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"The Department may cancel the passport in the following\nconditions:-\n(a) in case the passport holder informs the Department or the mission\nabout the lost passport issued in his or her name,\n(b) in case the passport is cancelled or revoked by the order of the Court,\n(c) in case the passport holder no longer remains a Nepali citizen,\n(d) in case it is proved that the non -Nepali citizen has received the\npassport,\n(e) in case the passport is received by providing false details,\n(f) in case the applicant does not receive the passport within the\nprescribed time after submitting the application.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"The Department shall provide information of cancellation of the passport\npursuant to clauses (a), (b), (c), (d) and (e ) of sub-section (1) to the concerned body of the\nGovernment of Nepal, foreign missions located in Nepal and office of the Interpol located\nin Nepal.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(3)","title":null,"content":"If any Nepali citizen submits an application in the mission for a new passport\nupon lost of his or her passport in the foreign country, the mission shall writ it to the\nDepartment to cancel such a passport specifying all the details of the passport holder and\nthe passport number and such information shall also be provided to the Immigration office\nat Nepal, Ministry responsible for foreign affairs of the country w here the concerned\nmission is located and the foreign missions in that country.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"16","title":"To use passport","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"The provisions on use of diplomatic and official passports shall be as\nprescribed.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"The holder of the diplomatic or official passport shall have to return such\npassport to the Department after the completion of the purpose pursuant to sub-section (1).\nProvided that the person bearing the prescribed public post may keep the diplomatic\nor special passport with himself or herself up to the term as prescribed.","children":[]}]}]},{"tier":1,"nodeType":"chapter","identifier":"Chapter-3","title":null,"content":"Regarding Travel Document and Seamans Record Book","children":[{"tier":2,"nodeType":"rule","identifier":"17","title":"Travel document","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"The Department and mission may issue a travel document.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"The terms and conditions for issuance of a travel document to be issued\npursuant to sub-section (1) shall be as prescribed.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"18","title":"Seamans passport","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"The Department or the mission may issue seamans passport to the\nNepali citizen who is going to work in ships.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"If an ordinary passport holder s ubmits an application for seamans passport to\nthe Department or mission enclosing the prescribed documents for the purpose of working\nin ships, the Department or mission shall issue seamans passport subject to the prescribed\nterms.","children":[]}]}]},{"tier":1,"nodeType":"chapter","identifier":"Chapter-4","title":null,"content":"Regarding Passport to be Issued in Temporary and Special Condition","children":[{"tier":2,"nodeType":"rule","identifier":"19","title":"Temporary passport may be issued","content":"The Mission may issue a temporary passport to the\nNepali citizen residing abroad if he or she submits an application for a new passport for\nexpiry of the valid term of the passport, lost, destroyed or by the reason of passport not\nbeing able to use being tempered, for a period not exceeding nine months till the issuance\nof a new passport.","children":[]},{"tier":2,"nodeType":"rule","identifier":"20","title":"Passport to be issued in special condition","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"In case any minor son or daughter of the\nNepali citizen resides abroad and has not acquired certificate of Nepali citizenship attaining\nsixteen years of age, submits an application enclosing prescribed documents along with the\nevidence that he or she has not acquired foreign citizenship or applied for the certificate of\nforeign citizenship, the mission may issue the ordinary passport in his or her name for a\nperiod not exceeding two years term for once.\nProvided that the mission may issue the ordinary passport for him or her for\nadditional two years term if he or she submits an application specifying the reason for not\nbeing able to acquire the certificate of Nepali citizenship as a result of force majeure.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"Such passport holder shall have to receive the ordinary passport by acquiring\nthe certificate of Nepali citizenship within the period pursuant to sub-section (1).","children":[]}]}]},{"tier":1,"nodeType":"chapter","identifier":"Chapter-5","title":null,"content":"Regarding Offence and Punishment","children":[{"tier":2,"nodeType":"rule","identifier":"21","title":"Offence","content":"If any one commits, cause to commit or abet the commission of any of the\nfollowing acts shall be considered as commission of an offence pursuant to this Act:-","children":[{"tier":3,"nodeType":"clause","identifier":"(a)","title":null,"content":"receives or attempts to receive a passport or travel document submitting false\ndetails,","children":[]},{"tier":3,"nodeType":"clause","identifier":"(b)","title":null,"content":"visits or attempts to visit a foreign country without having a passport or travel\ndocument pursuant to this Act,","children":[]},{"tier":3,"nodeType":"clause","identifier":"(c)","title":null,"content":"fails to abide by the order or direction issued by the Government of Nepal,","children":[]},{"tier":3,"nodeType":"clause","identifier":"(d)","title":null,"content":"uses the passport for the purpose other than the purpose for which it is issued,","children":[]},{"tier":3,"nodeType":"clause","identifier":"(e)","title":null,"content":"provides own passport for the use to other or uses other's passport,","children":[]},{"tier":3,"nodeType":"clause","identifier":"(f)","title":null,"content":"corrects photo or details in the passport,","children":[]},{"tier":3,"nodeType":"clause","identifier":"(g)","title":null,"content":"holds in controls other person's passport without his or her consent and with\nmalafide intention,","children":[]},{"tier":3,"nodeType":"clause","identifier":"(h)","title":null,"content":"performs any other act in contrary to this Act and the Rules framed under this\nAct.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"22","title":"Punishment","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"Anyone who commits the offence pursuant to clause (a), (b), (c), (d),\n(e)or (g) of section 21 shall be liable to the punishment with fine of two lakh rupees to five\nlakh rupees or with an imprisonment of one year to three years or with both.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"Anyone who commits the offence by committing any act contrary to this Act\nand the Rules framed under this Act other than those referred to in sub-section (1) shall be\nliable to the punishment with fine of fifty thousand rupees to one lakh rupees or with\nimprisonment of six months to one year or with both.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(3)","title":null,"content":"If anyon e who orders or abets to commit any offence shall be liable to the\npunishment as an offender referred to in sub-sections (1) and (2) and the accomplice to\nsuch an offence shall be liable to the half of the punishment imposed to the offender.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"23","title":"No obstruction to take action in accordance with prevailing laws","content":"If any act to be\nconsidered as an offence under this Act is also considered as offence under other prevailing\nlaws, nothing contained in this Act shall hinder to take action instituting the case under\nprevailing laws in respect to such an offence.","children":[]}]},{"tier":1,"nodeType":"chapter","identifier":"Chapter-6","title":null,"content":"Miscellaneous","children":[{"tier":2,"nodeType":"rule","identifier":"24","title":"Colour, Format and Size of Passport","content":"The colour, format and size of the passport to be\nissued pursuant to Sections 5, 17, 18, 19 and 20 shall be as prescribed.","children":[]},{"tier":2,"nodeType":"rule","identifier":"25","title":"Fees","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"No fees shall be imposed to issue diplomatic, official or service passport.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"The fees as prescribed, shall be imposed to issue ordinary passport, travel\ndocument, seamans passport, temporary passport and passport to be issued in special\nconditions.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"26","title":"Passport may be returned","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"The ordinary passport holder may return the passp ort\nissued in his or her name to the Department if it is not required by him or her or he or she\nis not in a situation to keep the passport with him or her because of any other reason thereto.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"The Department shall cancel the passport returned pursuant to sub-section (1).","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"27","title":"Electronic Record and Personalization","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"The Department shall conduct the act of\npassport personalization by processing the personal details of the applicant certified by the\nconcerned body and received with the applicati on for the passport also with the means of\ntechnology.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"The Department shall prepare and place securely the electronic record of\npassports, travel documents and seamans passports in a format as prescribed.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(3)","title":null,"content":"The details of the travel documents and seamans passports issued by the mission\nshall be sent to the Department in each three months.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"28","title":"To keep documents safe","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"The application filed for passport and also other documents\nenclosed shall be kept safely for twelve years from the date of issuance of the passport.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"The Department shall dispose the passports cancelled pursuant to this Act as\nprescribed.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(3)","title":null,"content":"The disposal procedure of the documents pursuant to sub-section (1) shall be in\naccordance with the prevailing laws.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"29","title":"Government to be Plaintiff","content":"The Government of Nepal shall be a plaintiff in the case of\noffence punishable under this Act and such cases shall be deemed to be included in the\nSchedule-1 of the National Criminal Procedure Code, 2017 (2074).","children":[]},{"tier":2,"nodeType":"rule","identifier":"30","title":"Appeal","content":"A person not satisfying with the decision of the Department for rejecting to issue\nthe passport or cancel the passport may file an appeal in the High Court of the province\nwhere the Department is situated within thirty five days of the receipt of informatio n of\nsuch rejection or cancellation.","children":[]},{"tier":2,"nodeType":"rule","identifier":"31","title":"Delegation of Power","content":"The Department may delegate some of its power s, obtained by it\nunder this Act, to other body or official as required.","children":[]},{"tier":2,"nodeType":"rule","identifier":"32","title":"Saving of the act done in good faith","content":"No employee shall be personally liable for the act\ndone in good faith under this Act.\nProvided that the provision of this Section shall not be considered to have been\nhindered to take any legal action to the consequence arising from the act done with\nnegligence.","children":[]},{"tier":2,"nodeType":"rule","identifier":"33","title":"Rules may be framed","content":"The Gover nment of Nepal may frame necessary Rules to\nimplement this Act.","children":[]},{"tier":2,"nodeType":"rule","identifier":"34","title":"Procedure may be framed","content":"The Ministry may frame necessary Procedure s without\nprejudice to the objective of the Act.","children":[]},{"tier":2,"nodeType":"rule","identifier":"35","title":"Repeal and Saving","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"Passport Act, 1976 (2024) has been hereby repealed.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"The acts performed in accordance with the Passport Act, 1976 (2024) shall be\nconsidered to have been performed in accordance with this Act.","children":[]}]}]}]}$LEGAL_9d26a67011a98f$::jsonb
)
